export function getCountryHub(code: string | null | undefined): [number, number] | null {
  if (!code) return null
  const up = code.trim().toUpperCase()
  return WORLD_COUNTRY_HUBS[up] || null
}

export function getCountryLabelOffset(
  code: string,
  hub: [number, number],
): { x: number; y: number; anchor: 'start' | 'middle' | 'end' } {
  const cc = code.trim().toUpperCase()
  if (cc === 'CN') return { x: hub[0] - 8, y: hub[1] - 8, anchor: 'end' }
  if (cc === 'SG') return { x: hub[0] + 8, y: hub[1] + 12, anchor: 'start' }
  if (cc === 'MA') return { x: hub[0] - 7, y: hub[1] + 15, anchor: 'end' }
  if (cc === 'TN') return { x: hub[0] + 4, y: hub[1] - 9, anchor: 'middle' }
  if (cc === 'EG') return { x: hub[0] - 4, y: hub[1] + 17, anchor: 'middle' }
  if (cc === 'LB') return { x: hub[0] + 8, y: hub[1] - 4, anchor: 'start' }
  if (cc === 'EU') return { x: hub[0] - 8, y: hub[1] - 7, anchor: 'end' }
  if (cc === 'FR') return { x: hub[0] - 8, y: hub[1] + 12, anchor: 'end' }
  if (cc === 'DE') return { x: hub[0] + 8, y: hub[1] - 7, anchor: 'start' }
  if (cc === 'JP' || cc === 'AU' || cc === 'PH') return { x: hub[0] + 8, y: hub[1] + 4, anchor: 'start' }
  if (cc === 'CA' || cc === 'MX' || cc === 'BR' || cc === 'AR') return { x: hub[0] + 8, y: hub[1] + 4, anchor: 'start' }
  return { x: hub[0] + 7, y: hub[1] - 6, anchor: 'start' }
}

export function buildRouteArcPath(srcCode: string, dstCode: string, index = 0): string {
  const s = getCountryHub(srcCode)
  const d = getCountryHub(dstCode)
  if (!s || !d || (s[0] === d[0] && s[1] === d[1])) return ''
  const mx = (s[0] + d[0]) / 2
  const my = (s[1] + d[1]) / 2
  const dx = d[0] - s[0]
  const dy = d[1] - s[1]
  const dist = Math.hypot(dx, dy)
  // 区分双向往返流向（东向西 vs 西向东）并叠加序号偏移，避免往返弧线重合遮挡
  const dirBump = dx > 0 ? 18 : 0
  const lift = Math.min(115, Math.max(24, dist * 0.22)) + dirBump + (index % 2 === 1 ? 14 : 0)
  const cx = Math.round(mx * 10) / 10
  const cy = Math.round(Math.max(14, my - lift) * 10) / 10
  return `M${s[0]},${s[1]} Q${cx},${cy} ${d[0]},${d[1]}`
}
